const listAIConversations = `-- name: ListAIConversations :many
SELECT id, uuid, organization_id, user_id, title, message_count, last_message_at, created_at, updated_at, deleted_at FROM ai_conversations
WHERE organization_id = $1
  AND user_id = $2
  AND deleted_at IS NULL
  AND ($3::text IS NULL OR title ILIKE '%' || $3 || '%')
ORDER BY COALESCE(last_message_at, created_at) DESC, id DESC
LIMIT $5 OFFSET $4
`

type ListAIConversationsParams struct {
	OrganizationID int64       `json:"organization_id"`
	UserID         int64       `json:"user_id"`
	Q              pgtype.Text `json:"q"`
	OffsetCount    int32       `json:"offset_count"`
	LimitCount     int32       `json:"limit_count"`
}

func (q *Queries) ListAIConversations(ctx context.Context, arg ListAIConversationsParams) ([]AiConversation, error) {
	rows, err := q.db.Query(ctx, listAIConversations,
		arg.OrganizationID,
		arg.UserID,
		arg.Q,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AiConversation{}
	for rows.Next() {
		var i AiConversation
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.UserID,
			&i.Title,
			&i.MessageCount,
			&i.LastMessageAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

