const sumAIOrganizationTokensSince = `-- name: SumAIOrganizationTokensSince :one
SELECT COALESCE(SUM(input_tokens + output_tokens + cache_write_tokens), 0)::bigint AS tokens
FROM ai_usage
WHERE organization_id = $1
  AND created_at >= $2
`

type SumAIOrganizationTokensSinceParams struct {
	OrganizationID pgtype.Int8        `json:"organization_id"`
	Since          pgtype.Timestamptz `json:"since"`
}

// Quota tokens = input + output + cache writes (cache reads are not counted).
func (q *Queries) SumAIOrganizationTokensSince(ctx context.Context, arg SumAIOrganizationTokensSinceParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumAIOrganizationTokensSince, arg.OrganizationID, arg.Since)
	var tokens int64
	err := row.Scan(&tokens)
	return tokens, err
}

