const upsertAIOrganizationSettings = `-- name: UpsertAIOrganizationSettings :one
INSERT INTO ai_organization_settings (organization_id, enabled, monthly_token_quota)
VALUES ($1, $2, $3)
ON CONFLICT (organization_id) DO UPDATE
SET enabled = EXCLUDED.enabled,
    monthly_token_quota = EXCLUDED.monthly_token_quota
RETURNING organization_id, enabled, monthly_token_quota, created_at, updated_at
`

type UpsertAIOrganizationSettingsParams struct {
	OrganizationID    int64       `json:"organization_id"`
	Enabled           bool        `json:"enabled"`
	MonthlyTokenQuota pgtype.Int8 `json:"monthly_token_quota"`
}

